// upscale of an already-small bitmap, which is what caused the blockiness.
// This is the same effective displayed size, just rasterized directly
// instead of upscaled, so it should look crisp without changing the clock's
// overall layout footprint.
//
// Generated from the same source (Ubuntu Mono Bold, fonts.gstatic.com) and
// DPI (141) as the rest of this codebase's fonts - calibrated by regenerating
// the existing 22pt size and confirming an exact byte-for-byte match against
// ubuntu_mono_all_b.h's bitmap data and glyph metrics before generating this
// size. Character range (0x20-0xB0) matches the other Ubuntu Mono fonts in
// this codebase for consistency, though only digits and ':' are needed here.

